const { chromium } = require('/home/daniel/ui-work/runs/202610271-as/sandbox/officehq-angular-spring/e2e/node_modules/playwright');
(async () => {
  const b = await chromium.launch({ args: ['--no-sandbox','--disable-dev-shm-usage','--disable-gpu'] });
  const page = await b.newPage();
  page.on('console', m => console.log('CONSOLE', m.type(), m.text().slice(0, 600)));
  page.on('pageerror', e => console.log('PAGEERR', e.message));
  await page.goto('http://localhost:3000/');
  await page.getByTestId('signin-name').fill('uma');
  await page.getByTestId('signin-submit').click();
  await page.getByTestId('sheet-id-input').fill('dbg' + Date.now());
  await page.getByTestId('sheet-load').click();
  await page.waitForTimeout(3000);
  console.log(await page.getByTestId('rate-form-grade').innerHTML());
  await b.close();
})();
EOF
curl -fsS localhost:3000/actuator/health; node $T/c.cjs 2>&1 | head -30
